export async function uploadPhoto(uri:string){
  const fd=new FormData();
  fd.append('file',{uri,name:'photo.jpg',type:'image/jpeg'} as any);
  const r=await fetch('{{upload_url}}',{method:'POST',body:fd,headers:{'Content-Type':'multipart/form-data'}});
  if(!r.ok)throw new Error('upload failed');
  return await r.json();}
